import { useEffect, useRef } from 'react';
import gsap from 'gsap';
import { useLanguage } from '../i18n/LanguageContext';
import { cn } from '../utils/cn';


interface PreloaderProps {
  onComplete: () => void;
}

export function Preloader({ onComplete }: PreloaderProps) {
  const { t, lang } = useLanguage();
  const containerRef = useRef<HTMLDivElement>(null);
  const lotusRef = useRef<SVGSVGElement>(null);
  const textRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (reduce) {
      // No intro animation: show the brand mark briefly, then hand off to the app.
      const tmo = window.setTimeout(onComplete, 600);
      return () => window.clearTimeout(tmo);
    }

    // Critical hero images to preload before entry
    const assets = [
      '/Politicians/models/mj_gautam_nobg.png',
      '/Politicians/models/modi_nobg.png',
      '/Politicians/models/amit_shah_nobg.png',
      '/Politicians/models/jp_nadda_nobg.png',
      '/Politicians/models/Dhami_nobg.png',
      '/Politicians/models/rp_nishank_nobg.png'
    ].map(path => {
      const clean = path.startsWith('/') ? path.slice(1) : path;
      return `${import.meta.env.BASE_URL}${clean}`;
    });

    let isCancelled = false;
    let ctx: gsap.Context | null = null;

    const preloadAll = async () => {
      const imgPromises = assets.map(src => {
        return new Promise<void>((resolve) => {
          const img = new Image();
          img.src = src;
          img.onload = () => resolve();
          img.onerror = () => resolve(); // Fallback: resolve anyway to avoid freeze on network drop
        });
      });

      // Video preloading wait (only on homepage, with a 4s fail-safe)
      const isHomepage = 
        window.location.pathname === '/' || 
        window.location.pathname === '/mg-portfolio' || 
        window.location.pathname === '/mg-portfolio/';

      const videoPromise = new Promise<void>((resolve) => {
        if (!isHomepage || (window as any).__videoReady) {
          resolve();
          return;
        }

        const tmo = setTimeout(() => {
          window.removeEventListener('video-ready', onReady);
          resolve();
        }, 4000);

        function onReady() {
          clearTimeout(tmo);
          window.removeEventListener('video-ready', onReady);
          resolve();
        }

        window.addEventListener('video-ready', onReady);
      });

      await Promise.all([...imgPromises, videoPromise]);

      if (!isCancelled) {
        ctx = gsap.context(() => {
          const tl = gsap.timeline({
            onComplete,
          });

          // Text fade in
          tl.from(textRef.current, {
            y: 20,
            opacity: 0,
            duration: 1,
            ease: "power2.out"
          })
          // Hold for experience
          .to({}, { duration: 1.5 })
          // Container fade out
          .to(containerRef.current, {
            opacity: 0,
            duration: 0.8,
            ease: "power2.inOut"
          });
        }, containerRef);
      }
    };

    preloadAll();

    return () => {
      isCancelled = true;
      if (ctx) ctx.revert();
    };
  }, [onComplete]);

  return (
    <div
      ref={containerRef}
      className="fixed inset-0 z-50 flex items-center justify-center bg-slateWhite select-none"
    >
      <div className="relative">
        <svg
          ref={lotusRef}
          className="lotus-loader w-[220px] h-[220px]"
          viewBox="0 0 2000 1962"
          xmlns="http://www.w3.org/2000/svg"
        >
          <g transform="translate(0.000000,1962.000000) scale(0.100000,-0.100000)">
            <path
              pathLength={1000}
              d="M10277 19088 c-57 -80 -338 -507 -492 -748 -471 -735 -901 -1493 -1140 -2008 -43 -95 -82 -172 -85 -172 -3 0 -43 66 -90 147 -520 893 -1247 1604 -2070 2022 -531 270 -1087 406 -1582 388 -150 -5 -193 -14 -325 -69 l-72 -29 96 -127 c527 -699 778 -1341 724 -1847 -12 -110 -59 -360 -84 -445 l-13 -45 -96 135 c-222 313 -388 510 -663 786 -279 279 -501 465 -785 655 -654 437 -1323 689 -2020 760 -189 20 -523 17 -640 -4 -170 -32 -338 -100 -428 -174 l-23 -18 77 -100 c575 -754 956 -1714 1099 -2769 41 -303 55 -521 65 -991 16 -761 54 -1169 160 -1710 224 -1134 708 -2157 1331 -2809 299 -313 679 -575 1026 -707 35 -13 63 -26 63 -29 0 -3 -30 -23 -66 -44 -187 -110 -419 -290 -597 -465 -362 -354 -548 -697 -564 -1036 -5 -111 -3 -126 20 -195 14 -41 37 -101 51 -132 l25 -57 53 36 c83 55 199 111 295 139 108 32 330 44 465 24 344 -50 730 -222 1125 -501 527 -374 961 -555 1528 -640 58 -9 181 -14 345 -14 227 0 266 3 358 23 150 33 253 67 379 127 l111 53 49 -35 c83 -60 276 -180 642 -400 195 -118 382 -236 416 -263 366 -292 632 -859 719 -1535 97 -758 -10 -1634 -289 -2345 -54 -139 -184 -404 -264 -538 -91 -155 -225 -338 -259 -356 -56 -29 -144 -46 -377 -75 -339 -42 -564 -56 -660 -42 -138 20 -841 7 -1035 -19 -56 -8 -69 -14 -94 -42 -61 -71 -101 -199 -85 -276 10 -47 72 -107 148 -144 l63 -30 262 -9 c654 -21 1292 -1 1536 47 131 26 356 147 525 283 486 390 785 1062 910 2046 49 385 58 561 64 1255 l6 655 50 -3 c92 -6 197 -66 235 -134 l23 -41 -6 -386 c-11 -647 -54 -1164 -138 -1666 -54 -320 -103 -506 -219 -830 -125 -351 -141 -385 -256 -544 -68 -96 -104 -155 -104 -172 0 -72 50 -155 171 -283 89 -94 112 -106 249 -131 157 -27 283 -36 580 -42 297 -6 448 4 494 30 16 9 183 12 636 12 518 1 632 4 720 18 200 31 264 60 310 141 36 61 37 88 7 141 -57 103 -192 111 -1117 70 -410 -18 -1448 -20 -1500 -2 -45 15 -52 52 -17 93 47 55 135 200 190 309 270 541 436 1388 497 2540 6 110 15 400 20 645 8 379 12 459 29 541 72 356 226 627 507 899 153 147 272 231 459 324 161 80 300 130 460 166 l100 23 70 -35 c248 -124 649 -187 1115 -175 408 11 757 100 1144 294 246 123 443 258 706 484 250 214 402 319 615 423 245 121 462 180 660 181 114 0 124 -2 196 -33 94 -40 244 -129 366 -215 l92 -66 35 107 c59 185 69 249 63 391 -20 446 -315 937 -794 1327 -59 48 -112 91 -116 95 -5 3 104 118 241 255 137 137 299 308 360 381 737 880 1192 1937 1317 3058 44 389 42 793 -5 1525 -43 658 -51 815 -58 1070 -12 464 8 693 93 1025 153 602 495 1219 950 1715 l87 94 -28 24 c-88 71 -229 130 -398 165 -86 17 -136 21 -331 21 -599 -1 -1140 -134 -1715 -425 -452 -229 -821 -499 -1206 -883 -321 -321 -547 -610 -786 -1005 -49 -81 -89 -138 -92 -130 -10 30 -36 158 -50 249 -33 211 -41 340 -41 645 0 276 3 324 23 440 65 377 181 717 379 1119 57 115 102 210 101 211 -12 11 -312 78 -404 90 -155 20 -199 19 -336 -10 -761 -158 -1514 -591 -2179 -1255 -267 -266 -466 -500 -683 -805 -59 -82 -111 -151 -115 -153 -5 -1 -21 26 -36 60 -249 562 -618 1283 -873 1708 -165 276 -396 616 -518 763 l-23 27 -44 -62z m-4804 -954 c864 -248 1774 -1113 2560 -2432 l115 -193 -70 -162 c-452 -1045 -729 -1984 -829 -2806 -40 -327 -37 -901 7 -1286 98 -864 394 -1651 834 -2217 27 -34 47 -64 46 -66 -6 -6 -230 70 -340 114 -254 104 -573 289 -771 449 -448 360 -818 832 -1110 1415 -424 848 -597 1747 -556 2900 22 630 74 1028 178 1370 70 230 154 622 193 895 71 508 35 988 -106 1415 -76 228 -174 415 -302 574 l-64 79 49 -8 c26 -4 101 -22 166 -41z m9247 -156 c-168 -359 -260 -770 -260 -1164 0 -270 60 -657 200 -1284 78 -346 212 -885 245 -980 135 -393 231 -1023 265 -1740 13 -277 13 -811 -1 -965 -74 -867 -413 -1599 -1024 -2211 -172 -173 -314 -291 -489 -407 -353 -236 -769 -394 -1186 -452 -63 -8 -130 -18 -147 -21 -18 -3 -33 -3 -33 0 0 3 33 56 73 118 315 485 643 1133 722 1428 93 348 149 1129 126 1750 -22 575 -77 1096 -161 1512 -55 271 -206 759 -361 1165 -143 374 -342 814 -518 1143 l-92 172 47 81 c72 125 241 379 334 502 130 171 222 277 385 444 561 573 1156 903 1795 996 144 21 136 30 80 -87z m-4270 -93 c1051 -1604 1750 -3180 2064 -4655 175 -819 229 -1677 145 -2265 -83 -577 -301 -1097 -650 -1545 -94 -122 -310 -343 -419 -430 -243 -193 -509 -328 -780 -394 -332 -80 -739 -74 -1087 19 -557 148 -1069 547 -1456 1135 -99 151 -255 458 -316 625 -259 702 -285 1514 -80 2500 278 1338 985 2920 2059 4610 155 244 382 585 390 585 4 0 63 -83 130 -185z m8264 -12 c-386 -433 -649 -966 -769 -1554 -61 -299 -78 -554 -65 -966 10 -288 18 -434 60 -1086 56 -869 48 -1279 -36 -1767 -134 -783 -466 -1539 -973 -2220 -511 -685 -1062 -1078 -1657 -1181 -270 -46 -590 -20 -880 72 l-31 10 162 162 c346 347 587 711 796 1199 157 367 282 834 334 1243 29 231 36 332 42 605 17 792 -101 1643 -393 2836 l-17 70 81 165 c563 1142 1467 2004 2464 2348 280 96 598 154 871 159 l98 2 -87 -97z m-17094 -24 c248 -21 522 -80 782 -168 901 -308 1793 -1019 2466 -1967 l72 -101 -15 -83 c-66 -376 -136 -904 -177 -1340 -16 -168 -15 -742 1 -975 85 -1240 389 -2276 899 -3059 100 -155 232 -328 342 -451 48 -54 76 -93 71 -98 -5 -5 -55 -22 -111 -38 -354 -99 -768 -84 -1135 41 -523 179 -1010 571 -1466 1180 -522 697 -841 1451 -953 2255 -30 210 -37 332 -46 790 -10 487 -19 666 -51 1020 -111 1224 -425 2240 -892 2889 -40 55 -75 105 -79 111 -8 13 91 11 292 -6z m5082 -8836 c363 -201 740 -354 1090 -442 l148 -37 -48 -59 c-161 -202 -281 -400 -337 -558 l-28 -78 6 -222 c6 -250 26 -422 67 -580 l27 -108 -26 -11 c-49 -19 -247 -67 -332 -79 -124 -19 -430 -16 -569 5 -490 73 -955 279 -1334 589 -307 253 -578 398 -892 477 -211 54 -418 57 -592 10 -40 -11 -74 -20 -77 -20 -3 0 5 24 16 53 65 165 181 329 350 492 181 174 393 325 649 458 l125 65 270 -55 c267 -54 271 -54 400 -49 258 12 589 76 845 165 63 22 121 40 127 40 7 1 59 -25 115 -56z m9448 -279 c267 -63 531 -332 669 -682 l21 -52 -28 7 c-53 15 -323 8 -412 -11 -410 -84 -847 -319 -1260 -676 -418 -362 -857 -567 -1286 -598 -144 -11 -492 1 -656 23 -186 24 -393 69 -386 83 151 289 192 463 193 817 0 206 -6 257 -47 385 -24 75 -78 186 -119 247 -16 23 -29 44 -29 48 0 12 205 103 304 134 127 41 293 69 426 73 89 2 120 -2 202 -24 238 -66 743 -98 981 -63 221 33 773 163 1167 274 121 34 169 37 260 15z m-7483 -449 c350 -126 780 -217 1233 -261 216 -21 740 -25 905 -6 407 46 706 112 1083 238 l193 65 51 -28 c166 -90 306 -310 347 -547 16 -86 13 -263 -4 -345 -35 -170 -120 -324 -254 -464 -132 -138 -291 -238 -486 -307 -381 -133 -770 -457 -882 -733 -99 -246 -270 -470 -415 -543 -100 -51 -235 -38 -388 37 -71 35 -101 59 -185 143 -68 69 -115 127 -148 183 -26 45 -68 108 -92 141 -114 151 -430 415 -709 592 -64 41 -163 104 -219 141 -254 163 -420 364 -505 612 -31 90 -36 117 -40 230 -12 321 88 618 265 789 43 41 126 98 145 98 4 0 51 -16 105 -35z"
            />
          </g>
        </svg>
      </div>
      <div 
        ref={textRef}
        className="absolute bottom-8 right-8 text-right font-hindi"
      >
        <p className={cn(
          "text-parliament font-medium text-lg",
          lang === 'en' ? "tracking-wide" : "tracking-normal"
        )}>{t.brand.name}</p>
        <p className={cn(
          "text-parliament/60 text-sm mt-1 uppercase text-[10px] font-sans font-bold",
          lang === 'en' ? "tracking-widest" : "tracking-normal"
        )}>{t.preloader.constituency} <span className="animate-pulse text-saffron ml-1">[ {t.preloader.loading} ]</span></p>
      </div>
    </div>
  );
}
